entries[173689] = { ["name"] = "Hastig eingepacktes Paket", ["text"] = "Questgegenstand\n\"Riecht stark nach Schwarzdornrosen und sollte nicht zu nahe ans Gesicht gehalten werden.\"" }
entries[173690] = { ["name"] = "Geweih eines Wolkenwanderers", ["text"] = "Questgegenstand\n\"Das perfekte Kauspielzeug für einen Larion.\"" }
entries[173691] = { ["name"] = "Animalauger", ["text"] = "Questgegenstand\nBenutzen: Entzieht dem anvisierten Wolkenwanderer Anima und speichert sie für spätere Verwendung." }
entries[173692] = { ["name"] = "Nemeas Wurfspeer", ["text"] = "Questgegenstand\nBenutzen: Schleudert einen Wurfspeer auf eine Großschwinge, was Andira als Zeichen zum Angriff dient. (10 Sek. Abklingzeit)\n\"Wird normalerweise mit einem Larion verwendet, um fliegende Beute zu jagen.\"" }
entries[173693] = { ["name"] = "Krug mit Maden", ["text"] = "Questgegenstand\nBenutzen: Streut Maden auf ein totes Ziel, die sämtliches nutzbares Fleisch vernichten." }
entries[173694] = { ["name"] = "Nachtmarktvorlage", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Hier sollte etwas Bewegendes stehen.\"" }
entries[173695] = { ["name"] = "Venthyrritualrobe", ["text"] = "Questgegenstand\nEinzigartig\n\"Reich geschmückt, elegant und wunderschön.\"" }
entries[173696] = { ["name"] = "Venthyrritualdolch", ["text"] = "Questgegenstand\nEinzigartig\n\"Hat endlosen Seelen geholfen, ohne je Fleisch zu durchstoßen.\"" }
entries[173697] = { ["name"] = "Venthyrritualfoliant", ["text"] = "Questgegenstand\nEinzigartig\n\"Jedes Ritual ist unermesslich detailliert und hat unzählige Varianten.\"" }
entries[173698] = { ["name"] = "Schriftrolle von Karazhan", ["text"] = "Questgegenstand\nBenutzen: Teleportiert den Benutzer in die Verwüsteten Lande." }
entries[173699] = { ["name"] = "Schriftrolle der Verwüsteten Lande", ["text"] = "Questgegenstand\nBenutzen: Teleportiert den Benutzer in die Verwüsteten Lande.\n1 Aufladung" }
entries[173700] = { ["name"] = "Knochenbinder Zals Schlüssel", ["text"] = "Questgegenstand\nEinzigartig anlegbar" }
entries[173702] = { ["name"] = "Wolkenfederessenz", ["text"] = "Questgegenstand\n\"Das Leibgericht aller Larions.\"" }
entries[173703] = { ["name"] = "Reinheitskrug", ["text"] = "Questgegenstand\nBenutzen: Der Affenkönig hat Euch diesen Krug für den Fall gegeben, dass Ihr Hilfe bei seinen Rätseln braucht. Wenn Ihr den Inhalt trinkt, findet Ihr vielleicht eher den richtigen Weg. Aber warum riecht er so seltsam?\n1 Aufladung\nVerkaufspreis:" }
entries[173704] = { ["name"] = "Kornkammerkrug", ["text"] = "Questgegenstand\nBenutzen: Der Affenkönig hat Euch diesen Krug für den Fall gegeben, dass Ihr Hilfe bei seinen Rätseln braucht. Wenn Ihr den Inhalt trinkt, findet Ihr vielleicht eher den richtigen Weg. Es hört sich an, als wäre Reis in dieses Getränk gemischt.\n1 Aufladung\nVerkaufspreis:" }
entries[173705] = { ["name"] = "Die Venthyrtagebücher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine Sammlung persönlicher Tagebucheinträge namhafter Venthyr. Sehr begehrt bei Personen, die mehr über ihr Alltagsleben erfahren wollen.\"" }
entries[173706] = { ["name"] = "Jadekrug", ["text"] = "Questgegenstand\nBenutzen: Der Affenkönig hat Euch diesen Krug für den Fall gegeben, dass Ihr Hilfe bei seinen Rätseln braucht. Wenn Ihr den Inhalt trinkt, findet Ihr vielleicht eher den richtigen Weg. Wie eine spektrale Version des Affenkönigs Euch dies geben konnte, ist wiederum auch ein Rätsel.\n1 Aufladung\nVerkaufspreis:" }
entries[173707] = { ["name"] = "Seelenjägerklinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Klinge eines Venthyrrapiers. Ein Blick darauf verrät sofort seine mörderische Vergangenheit.\"" }
entries[173708] = { ["name"] = "Kyrianischer Schild", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Werfen!\n\"Ein amüsanter Weg, eine Bindung mit Eurem Larion einzugehen.\"" }
entries[173709] = { ["name"] = "Phiole Gräberschlamm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Enthält Schlamm aus einer Schlammlache. Der Geruch ist abscheulich und versengt Eure Nasenhaare.\"" }
entries[173710] = { ["name"] = "Versteinertes Steinscheusal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Anima des Steinscheusals wurde gänzlich entzogen. Davon abgesehen ist es in sehr gutem Zustand.\"" }
entries[173711] = { ["name"] = "Porträt von Graf Denathrius", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine beinahe perfekte Darstellung von Denathrius.\"" }
entries[173712] = { ["name"] = "Seelenregister", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein Register, das die Namen tausender Seelen beinhaltet, die nach Revendreth geschickt wurden.\"" }
entries[173713] = { ["name"] = "Boshaftes weißes Knochenross", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares boshaftes weißes Knochenross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Kaum ein anderes Reittier ermöglicht einen Ritt in die Schlacht mit so vielen Stacheln und Knochen.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
entries[173714] = { ["name"] = "Boshafter weißer Kriegssäbler", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren boshaften weißen Kriegssäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Streicheleinheiten am Bauch sind nicht erwünscht und bringen nur Ärger.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1" }
entries[173715] = { ["name"] = "Gräberwerkzeugsatz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein Eimer voller Werkzeuge, die von den Gräbern von Revendreth verwendet werden.\"" }
entries[173716] = { ["name"] = "Moosbewachsener Ruhestein", ["text"] = "Questgegenstand\nBenutzen: Teleportiert den Benutzer zur Mondlichtung.\n1 Aufladung" }
entries[173717] = { ["name"] = "Perfektionierter Handspiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieser Gegenstand dient zur Teleportation oder auch zum Einsatz im Kampf. Der Rahmen des Spiegels ist aufwendig verziert.\"" }
entries[173718] = { ["name"] = "Flasche Redelavwein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine Flasche gut gealterten Redelavweins. Eine einmalige Mischung von natürlichen Gewürzen und Blättern aus Revendreth. Im Abgang schmeckt der Wein stark nach Eisen.\"" }
entries[173719] = { ["name"] = "Makelloser Fleddermauszahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein sehr spitzer Zahn. Ein leichter Stoß kann bereits die Haut durchdringen.\"" }
entries[173720] = { ["name"] = "Glitzernde Primulahalskette", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Halskette ist mit einem merkwürdigen goldenen Material verziert.\"" }
entries[173721] = { ["name"] = "Liebe und Terror", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine Sammlung von Gedichten eines unbekannten Autors. Der Schreibstil legt nahe, dass sie von einem Venthyr verfasst wurden.\"" }
entries[173726] = { ["name"] = "Kiste mit schwach leuchtenden 'Luft'löchern", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[173727] = { ["name"] = "Nomis Jahrgang", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Nimmt einen Schluck von Nomis Jahrgang, der ein Feuerwerk für die Sinne bietet! Kann nur in Zandalar, Kul Tiras und Nazjatar benutzt werden. (10 Min Abklingzeit)\n\"Eine duftende Mischung aus Früchten und Feuerblüte.\"\nVerkaufspreis:" }
entries[173728] = { ["name"] = "Fleischige Exopoditen", ["text"] = "Questgegenstand\n\"Lecker, wenn man so etwas mag.\"" }
entries[173732] = { ["name"] = "Seltsamer Runenstein", ["text"] = "Questgegenstand\n\"In den Stein wurde auf brutale Weise eine seltsame Rune eingeschlagen.\"" }
entries[173733] = { ["name"] = "Sündensteinaufzeichnungen", ["text"] = "Questgegenstand\n\"Ein komplettes Archiv würde detailliert alle Sündensteine auflisten, die die Venthyr jemals angesammelt haben.\"" }
entries[173734] = { ["name"] = "Geheimnisvolle Kiste", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[173735] = { ["name"] = "Sühnengruftschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[173736] = { ["name"] = "Vielschichtiger Informationskern der automatisierten Wertschätzung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 250 Ruf beim Rostbolzenwiderstand, bis maximal zu einem ehrfürchtigen Ruf. (2 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[173737] = { ["name"] = "Temels Körper", ["text"] = "Questgegenstand\nEinzigartig\n\"Überall sieht man Risse. Die Schläger des Kämmerers haben ihn übel zugerichtet.\"" }
entries[173738] = { ["name"] = "Temels Flügel", ["text"] = "Questgegenstand\nEinzigartig\n\"Einer ist etwas größer als der andere.\"" }
entries[173739] = { ["name"] = "Temels Kopf", ["text"] = "Questgegenstand\nEinzigartig\n\"Ist von einem heftigen Kicheranfall wie gelähmt.\"" }
