entries[173793] = { ["name"] = "Sündenstein eines Inquisitors", ["text"] = "Wird beim Aufheben gebunden\n\"Archivar Fane wird für Euch den Sündenstein eines Inquisitors ausfindig machen, den Ihr herausfordern könnt.\"" }
