entries[173800] = { ["name"] = "Ausdruckslose Maske", ["text"] = "Questgegenstand\n\"Eine merkwürdige Maske, die von feindlichen Fae getragen wird.\"" }
entries[173810] = { ["name"] = "Dunkelsichttrank", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verzerrt die Sinne des Anwenders und gewährt im die Sehfähigkeit, verborgene Gegner zu entdecken. (5 Sek. Abklingzeit)\n\"Er ist ungewöhnlich leicht und fühlt sich kalt an. Der Geruch erinnert an verrottende Kadaver.\"" }
