entries[173880] = { ["name"] = "Geläutertes Metall", ["text"] = "Questgegenstand\n\"Die Verhüttung hat anscheinend alle Spuren der Magie der Verschmähten entfernt.\"" }
entries[173881] = { ["name"] = "Schlickpumpe", ["text"] = "Questgegenstand\nBenutzen: Aktiviert eine Schlickpumpe, um bergungsfähige Ausrüstung aus dem nahe gelegenen blubbernden Schlick zu holen. (30 Sek. Abklingzeit)" }
entries[173882] = { ["name"] = "Seelenstahlklammern", ["text"] = "Questgegenstand\n\"Ein spezielles Paar Klemmen mit einem Seelenstahlkern, die gewaltige Kräfte aushalten.\"" }
entries[173883] = { ["name"] = "Replizierende Leerentropfen", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die Formlose Leere'.\nGroße Macht:\nReplikation des Wissens\n40 Meter Reichweite\nWirken in 1.5 sek. Repliziert die Energie im Herz von Azeroth Eures Ziels und gewährt Euch 15 Sek. lang Zugriff auf Rang 1 seiner derzeit ausgerüsteten großen Essenz. Die Abklingzeit von 'Die Formlose Leere' ist um 50% länger als die normale Abklingzeit der von Euch replizierten Essenz.\n\nFunktioniert nicht bei passiven Essenzen.\nGeringe Macht:\nSymbiotische Präsenz\n40 Meter Reichweite Jedes Mal, wenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhaltet Ihr 20 Sek. lang 22 Hauptwert .\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.\n\"Niederträchtig und doch äußerst machtvoll.\"" }
entries[173884] = { ["name"] = "Wachsender Leerentropfen", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die Formlose Leere'.\nGroße Macht:\nReplikation des Wissens\n40 Meter Reichweite\nWirken in 1.5 sek. Repliziert die Energie im Herz von Azeroth Eures Ziels und gewährt Euch 15 Sek. lang Zugriff auf Rang 2 seiner derzeit ausgerüsteten großen Essenz. Die Abklingzeit von 'Die Formlose Leere' ist um 40% länger als die normale Abklingzeit der von Euch replizierten Essenz.\n\nFunktioniert nicht bei passiven Essenzen.\nGeringe Macht:\nSymbiotische Präsenz\nJedes Mal, wenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhaltet Ihr für 20 Sek. [Quellwert] Hauptwert.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.", ["unresolvedValues"] = true }
entries[173885] = { ["name"] = "Instabiler Leerentropfen", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die Formlose Leere'.\nErlernt mit einem anderen Charakter 'Rang 3 - Die Formlose Leere', um diese Essenz freizuschalten.\nGroße Macht:\nReplikation des Wissens\n40 Meter Reichweite\nWirken in 1.5 sek. Repliziert die Energie im Herz von Azeroth Eures Ziels und gewährt Euch 15 Sek. lang Zugriff auf Rang 3 seiner derzeit ausgerüsteten großen Essenz. Die Abklingzeit von 'Die Formlose Leere' ist um 30% länger als die normale Abklingzeit der von Euch replizierten Essenz.\n\nFunktioniert nicht bei passiven Essenzen.\nGeringe Macht:\nSymbiotische Präsenz\nJedes Mal, wenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhaltet Ihr für 20 Sek. [Quellwert] Hauptwert und 18 Tempo.\n\nDer Verbündete, der eine Azeritessenz eingesetzt hat, erhält ebenfalls für 20 Sek. 18 Tempo. Es kann immer nur ein Verbündeter diesen Tempoeffekt haben.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.", ["unresolvedValues"] = true }
entries[173886] = { ["name"] = "Ausbrechender Leerentropfen", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die Formlose Leere'.\nGroße Macht:\nReplikation des Wissens\n40 Meter Reichweite\nWirken in 1.5 sek. Repliziert die Energie im Herz von Azeroth Eures Ziels und gewährt Euch 15 Sek. lang Zugriff auf Rang 3 seiner derzeit ausgerüsteten großen Essenz. Die Abklingzeit von 'Die Formlose Leere' ist um 30% länger als die normale Abklingzeit der von Euch replizierten Essenz.\n\nFunktioniert nicht bei passiven Essenzen.\nGeringe Macht:\nSymbiotische Präsenz\nJedes Mal, wenn ein Verbündeter innerhalb von 40 Metern eine Azeritessenz einsetzt, erhaltet Ihr für 20 Sek. [Quellwert] Hauptwert und 18 Tempo.\n\nDer Verbündete, der eine Azeritessenz eingesetzt hat, erhält ebenfalls für 20 Sek. 18 Tempo. Es kann immer nur ein Verbündeter diesen Tempoeffekt haben.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.", ["unresolvedValues"] = true }
entries[173887] = { ["name"] = "Kralle von Ha-Li", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ha-Lis Brut ist am blauen Himmel Pandarias zu Hause und jagt dort arglose Beute.\"\nBeute von:\nHa-Li\nZone:\nTal der Ewigen Blüten" }
entries[173888] = { ["name"] = "Splitter der Selbstopferung", ["text"] = "Vision der Wirbelnden Sande\nEinzigartig (5)\nBenutzen: Opfert 25 geistige Gesundheit, um den verursachten körperlichen Schaden eines Verbündeten 30 Sek. lang um 10% zu erhöhen.\n\nDieser Effekt ist bis zu 5-mal stapelbar. (5 Sek. Abklingzeit)\n\"Spuren von Verderbnis bleiben zurück. Sie sind recht verlockend.\"" }
entries[173891] = { ["name"] = "Seuchengeborener Schleim", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
