entries[173922] = { ["name"] = "Kyrianische Brustplatte", ["text"] = "Questgegenstand\n\"Leicht, aber stabil. Es sind keine Spuren von Beschädigungen zu erkennen.\"" }
entries[173923] = { ["name"] = "Kyrianische Stiefel", ["text"] = "Questgegenstand\n\"Die Schrammen an den Zehen zeigen, dass Ismini notfalls nicht vor einem Kampf ohne Waffen zurückschreckt.\"" }
entries[173924] = { ["name"] = "Kyrianischer Helm", ["text"] = "Questgegenstand\n\"Ein verzierter Helm, der einem hochrangigen Mitglied des Tempels des Mutes gehört hat.\"" }
entries[173925] = { ["name"] = "Kyrianische Schulterstücke", ["text"] = "Questgegenstand\n\"Trotz des dekorativen Aussehens sehr stabil.\"" }
