entries[173932] = { ["name"] = "Faustwaffe des Ardenwaldpakts", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Faustwaffe\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[173934] = { ["name"] = "Teilweise verdaute Nudeln", ["text"] = "\"Vielleicht auch etwas ganz anderes?\"\nVerkaufspreis:" }
entries[173935] = { ["name"] = "Nik-Niks Glitschistecher", ["text"] = "Wird beim Anlegen gebunden\nWaffenhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[173936] = { ["name"] = "Knatzeliger, verfiddelter Stecken", ["text"] = "Wird beim Anlegen gebunden\nWaffenhand Stab\n2 - 5 Schaden Geschwindigkeit 2.60\n(1.3 Schaden pro Sekunde)\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[173937] = { ["name"] = "Abgetrennter Oculus", ["text"] = "Benutzen: Zerquetscht das Auge.\n\"Das herrenlose Auge erwidert Euren Blick, egal wohin Ihr schaut.\"\nVerkaufspreis:" }
entries[173939] = { ["name"] = "Verlockende Anima", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermächtigt die Weltenrandkohlenpfannen, um einen mächtigen Verschlinger anzulocken. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[173940] = { ["name"] = "Zeichen des Schutzes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nBenutzen: Eure Haut wird härter und absorbiert 8 Sek. lang [ 901 * (1 + Vielseitigkeit)] Schaden.\n\nDas Erleiden von magischem Schaden erhöht die verbleibende Absorption um 113 und die Dauer um 2 Sek., bis zu einem Maximum von [Quellwert] Schaden bzw. 16 Sek. (2 Min Abklingzeit)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[173941] = { ["name"] = "Monströser Schädel", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[173942] = { ["name"] = "Markbohrlarve", ["text"] = "Questgegenstand" }
entries[173943] = { ["name"] = "Qual im Glas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nAnlegen: Eure Angriffe haben eine Chance, einen Rest von Azsharas Qual zu entfesseln, der allen Gegnern in der Nähe 1 Schattenschaden zufügt und Euch 'Entfesselte Qual' gewährt. 'Entfesselte Qual' erhöht den Schaden dieses Effekts um 100%. Wenn 12 Stapel erreicht werden, werden diese aufgebraucht, um allen Gegnern in der Nähe 45 Schattenschaden zuzufügen.\nVerkaufspreis:" }
entries[173944] = { ["name"] = "Verbotene Obsidianklaue", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nBenutzen: Entzieht dem Ziel seine Lebenskraft, fügt ihm so im Verlauf von 8.5 Sek. 130 Schattenschaden zu und stellt dabei [Quellwert] Eures Manas wieder her. (2 Min Abklingzeit)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[173945] = { ["name"] = "Schließt Euch dem Prinzen an!", ["text"] = "Questgegenstand\n\"In eleganter Handschrift verfasst.\"\n<Zum Lesen rechtsklicken>" }
entries[173946] = { ["name"] = "Zuckendes Segment von Drest'agath", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nBenutzen: Verursacht eine Eruption abscheulicher Stacheln, die alle Gegner in der Nähe treffen und ihnen 349 körperlichen Schaden zufügen. (1 Min, 20 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[173947] = { ["name"] = "Glitzernde Abgrundmuschel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 250 Ruf bei den Ankoanern der Meeresklinge, bis maximal zu einem ehrfürchtigen Ruf. (2 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[173948] = { ["name"] = "Glitzernde Abgrundmuschel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 250 Ruf bei den Entfesselten, bis maximal zu einem ehrfürchtigen Ruf. (2 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[173949] = { ["name"] = "Bergungsgut von der Kette des Schreckens", ["text"] = "Wird beim Aufheben gebunden\n\"Geborgene Güter der von Mogu, Kvaldir, Eistrollen und wilden Yetis bewohnten Insel im Norden.\"\n<Zum Öffnen rechtsklicken>" }
entries[173950] = { ["name"] = "Bergungsgut von Wappenfall", ["text"] = "Wird beim Aufheben gebunden\n\"Geborgene Güter der von rastlosen Orcseelen, Zwielichtdrachen und Piraten bewohnten Schlachtfeldinsel.\"\n<Zum Öffnen rechtsklicken>" }
entries[173951] = { ["name"] = "N'lyeth, Splitter von N'Zoth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Opfert einen Teil Eurer sterblichen Essenz und fügt Euch selbst Schattenschaden in Höhe von 60% Eurer maximalen Gesundheit zu.\n\nIm Gegenzug werdet Ihr zu einem Shath'Yar, verliert Eure normale Fraktionstreue und dient nur noch N'Zoth.\n\nN'lyeth kann nur im Freien in Kul Tiras und Zandalar sowie in Visionen von N'Zoth verwendet werden, während Ihr Euch im Kriegsmodus befindet. (1 Stunde Abklingzeit)" }
entries[173952] = { ["name"] = "Grabnatapfel", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Diese merkwürdig schwammige Frucht gibt ein schwaches, ungesund grünes Leuchten von sich.\"" }
