entries[174049] = { ["name"] = "Kugel des finstersten Wahnsinns", ["text"] = "Wird beim Aufheben gebunden\n\"Wird in verstörenden Visionen gefunden, wenn Ziele abgeschlossen werden, während die Effekte aller Gesichtslosenmasken aktiv sind.\"" }
entries[174050] = { ["name"] = "Verderbter Ring - Gewalt genießen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 15.\nAnlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\nAnlegen: Eure Todesstöße lassen Euch die Gewalt genießen und machen Euch 6 Sek. lang bewegungsunfähig.\nVerkaufspreis:" }
entries[174051] = { ["name"] = "Verderbter Ring - Spontaner Zorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 15.\nAnlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\nAnlegen: Markiert regelmäßig einen zufälligen Gegner, der so zum Ziel Eures Zorns wird. Während Euer Zorn anhält, wird der Schaden, den Ihr anderen Gegnern zufügt, um 10% verringert. (45s Abklingzeit)\nVerkaufspreis:" }
entries[174052] = { ["name"] = "Verderbter Ring - Masochistisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 15.\nAnlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\nAnlegen: Wenn Eure Gesundheit unter 25% fällt, verspottet Ihr 5 Sek. lang alle Gegner in der Nähe.\nVerkaufspreis:" }
entries[174053] = { ["name"] = "Verderbter Ring - Übermütig", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 15.\nAnlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\nAnlegen: Wenn Ihr überschüssige Heilung erhaltet, lehnt Ihr die nächsten (Gesamtgesundheit * 25 / 100) Heilung innerhalb von 10 Sek. ab.\nVerkaufspreis:" }
entries[174054] = { ["name"] = "Verderbter Ring - Letzter Griff", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 15.\nAnlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\nAnlegen: Wenn Ihr einen Gegner tötet, wird an dessen Position ein feindliches Tentakel beschworen, das versucht, Euch mit 'Leerengriff' zu treffen.\nVerkaufspreis:" }
entries[174055] = { ["name"] = "Verderbter Ring - Ding aus dem Jenseits", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+7 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 16.\nAnlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\nAnlegen: Das Ding aus dem Jenseits erhebt sich regelmäßig in Eurer Nähe und greift Euch an. Seine Bewegungsgeschwindigkeit erhöht sich entsprechend der Verderbnis.\nVerkaufspreis:" }
entries[174056] = { ["name"] = "Verderbter Ring - Der Wahrheit ins Auge sehen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 15.\nAnlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\nAnlegen: Eine unsägliche Schriftrolle erscheint in Eurer Nähe, die nur Ihr und andere mit dieser Verderbnis sehen können. Jede Sekunde, in der Ihr sie nicht anseht, erleidet Ihr 0 Schaden. Wenn sie Euch 5-mal Schaden zugefügt hat, werdet Ihr 6 Sek. lang in Angst und Schrecken versetzt.\nVerkaufspreis:" }
entries[174057] = { ["name"] = "Verderbter Ring - Hypnotisierend", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+6 Ausdauer\nErhöht Eure Tempowertung um + 7.\nErhöht Eure Meisterschaftswertung um + 15.\nAnlegen: Euer Schaden und Eure Heilung werden um 2% erhöht.\nAnlegen: Eure Schadenszauber und -fähigkeiten gegen dasselbe Ziel verringern Eure Bewegungsgeschwindigkeit 6 Sek. lang um 5%. Dieser Effekt ist bis zu 10-mal stapelbar.\nVerkaufspreis:" }
entries[174058] = { ["name"] = "Animareserve", ["text"] = "Questgegenstand\n\"Mikanikos' spezielle Animareserve.\"" }
entries[174059] = { ["name"] = "Panzeranzug X-52", ["text"] = "Questgegenstand\nBenutzen: Legt den Panzeranzugprototypen X-52 an. (5 Sek. Abklingzeit)" }
entries[174060] = { ["name"] = "Psychenreißer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, die Psyche des Gegners zu zerfetzen und ihm 76 Schattenschaden zuzufügen. Zusätzlich erleidet er dadurch 10 Sek. lang 5 zusätzlichen Schattenschaden durch Eure Zauber und Fähigkeiten. (10s Abklingzeit)\nVerkaufspreis:" }
entries[174061] = { ["name"] = "Phaestus, Genesis der Äonen", ["text"] = "Questgegenstand\n\"Gesegnetes Instrument der Ersten Schmiedin, Medium der Erschaffung des ersten Zenturios und der Spitzen des Aufstiegs.\"" }
