entries[174066] = { ["name"] = "Karawanenhyäne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Den Baldachin über diesem Dünenläufer könnt Ihr an Eurer Lagerstelle verwahren, falls Ihr lieber den Wind im Fell spüren möchtet.\"\nErfolg:\nVerbündete Völker: Vulpera" }
entries[174067] = { ["name"] = "Roboschreiter von Mechagon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die besten Reittiere können logischerweise mehrere Zwecke erfüllen. Manchmal muss man eben von A nach B gelangen und im Anschluss auch noch an irgendetwas herankommen, das sich ganz weit oben befindet.\"\nErfolg:\nVerbündete Völker: Mechagnome" }
entries[174068] = { ["name"] = "Wappenrock von Mechagon", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nVölker: Mechagnom" }
