entries[174092] = { ["name"] = "Mateos Spiegelscherbe", ["text"] = "Questgegenstand\n\"Wurde dem Sündenhüter Mateo anvertraut, bevor der Kurator in den Schlund verbannt wurde. Kann mit Emils Scherbe kombiniert werden, um den Spiegel des Kurators zu vervollständigen.\"" }
