entries[174271] = { ["name"] = "Bauplan: Sturmstahlvernichter des unheimlichen Kämpfers", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Sturmstahlvernichter des unheimlichen Kämpfers effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Sturmstahlvernichters des unheimlichen Kämpfers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nAllianz\nSturmstahlvernichter des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n15 Schaden Geschwindigkeit 3.00\n(5.0 Schaden pro Sekunde)\n+7 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nVerkaufspreis:\nHorde\nSturmstahlvernichter des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n15 Schaden Geschwindigkeit 3.00\n(5.0 Schaden pro Sekunde)\n+7 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nVerkaufspreis:\nBenötigt Osmeniterz (30), Sturmsilbererz (8), Isoliertes Kabel (18), Expulsom (6)" }
entries[174272] = { ["name"] = "Bauplan: Sturmstahlvernichter des unheimlichen Kämpfers", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Sturmstahlvernichter des unheimlichen Kämpfers effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Sturmstahlvernichters des unheimlichen Kämpfers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nAllianz\nSturmstahlvernichter des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n15 Schaden Geschwindigkeit 3.00\n(5.0 Schaden pro Sekunde)\n+7 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nVerkaufspreis:\nHorde\nSturmstahlvernichter des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n15 Schaden Geschwindigkeit 3.00\n(5.0 Schaden pro Sekunde)\n+7 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nVerkaufspreis:\nBenötigt Osmeniterz (25), Sturmsilbererz (7), Isoliertes Kabel (15), Expulsom (5)" }
entries[174273] = { ["name"] = "Bauplan: Diskombobulator des unheimlichen Kämpfers", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Diskombobulator des unheimlichen Kämpfers effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Diskombobulators des unheimlichen Kämpfers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nDiskombobulator des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n8 - 11 Schaden Geschwindigkeit 2.60\n(3.7 Schaden pro Sekunde)\n+3 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 110 / 110\nVerkaufspreis:\nBenötigt Osmeniterz (17), Sturmsilbererz (6), Isoliertes Kabel (10), Expulsom (4)" }
