entries[174275] = { ["name"] = "Abgefallene Purianfrucht", ["text"] = "Questgegenstand" }
entries[174276] = { ["name"] = "Bresche des verderbten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Macht Euch die Verderbnis gegnerischer Spielercharaktere zunutze, um für 6 Sek. ein Tor zu öffnen, durch das Träger dieses Schmuckstücks bis zu 6 Sek. lang in die Leere entschwinden können. Das Betreten der Leere gewährt 40 Geschwindigkeit und macht Euch für Spielercharaktere außerhalb der Leere unsichtbar.\n\nBeim Verlassen der Leere wird Euer erlittener Schaden für 6 Sek. um 10% erhöht. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[174277] = { ["name"] = "Anhaltender psychischer Panzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+8 [Beweglichkeit oder Stärke]\nBenutzen: Verringert Euren erlittenen Schaden 8 Sek. lang um 80%, bis Euer psychischer Panzer insgesamt 919 Schaden erlitten hat. (1 Min Abklingzeit)\nAnlegen: Während Ihr in Ny'alotha seid, wird die Menge Eurer erhaltenen Schadensverringerung basierend auf Eurem Verderbniswiderstand um bis zu 50% weiter erhöht.\nVerkaufspreis:" }
