entries[174287] = { ["name"] = "Funken der Unerschütterlichen Kraft", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 45 Funken der Unerschütterlichen Kraft, um [ein Handbuch der unausgewogenen Taktiken][einen Schutz der gegenseitigen Hilfe] zu erschaffen, womit das Herz von Azeroth mit ['Stärke des Wächters']['Unnachgiebiger Schutz'] verstärkt werden kann. Der erschaffene Gegenstand hängt von Eurer Beutespezialisierung ab." }
