entries[174348] = { ["name"] = "Gegrillter Knirscher", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt.\n\nWährend Ihr satt seid, nehmt Ihr für 10 Min. die Gestalt eines K'thir an, was die Entfernung verringert, aus der Gegner in einer Vision von N'Zoth Euch angreifen.\nVerkaufspreis:" }
entries[174349] = { ["name"] = "Grässliches Gulasch", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt.\n\nWährend Ihr satt seid, regeneriert Ihr in Visionen von N'Zoth pro Sekunde 2% Eurer maximalen Gesundheit.\nVerkaufspreis:" }
entries[174350] = { ["name"] = "Dubiose Delikatesse", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt.\n\nWährend Ihr satt seid, wird die Dauer von erlittenen Kontrollverlusteffekten in Visionen von N'Zoth um 20% verringert.\nVerkaufspreis:" }
entries[174351] = { ["name"] = "K'Bap", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nWenn Ihr mehr als 10 Sek. mit Essen verbringt, stellt Ihr sofort 100 geistige Gesundheit wieder her. (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[174352] = { ["name"] = "Gebackene Leerenflosse", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt.\n\nWährend Ihr satt seid, ist Eure Bewegungsgeschwindigkeit in Visionen von N'Zoth um 20% erhöht.\nVerkaufspreis:" }
