entries[174361] = { ["name"] = "Schwarzer Drachenschuppenrucksack", ["text"] = "Kosmetisch\nWird beim Aufheben gebunden\nRücken\n3 Rüstung\nErfordert den Erfolg \"Wir haben die Technologie\".\nErfordert den Erfolg \"Gemeinsame Erinnerungen\", bei dem alle Aufwertungen für das Stundenglas der verstörenden Visionen freigeschaltet werden müssen.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
