entries[174373] = { ["name"] = "Goldbrauner Nachtsäbler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen goldbraunen Nachtsäbler beschwört.\nBeschwört einen reitbaren goldbrauner Nachtsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nSchließt die Schlacht um die Dunkelküste auf dem Schwierigkeitsgrad 'Heroisch' ab.\n\n\"Nachtsäbler dieser Farbe sind sehr selten und kaum zu finden. Bei Jägerinnen erfreuen sie sich großer Beliebtheit.\"\nVerkäufer:\nVersorgerin Starkschmied\nZone:\nTiragardesund\nKosten:\n350\n\nVerkäufer:\nVersorgerin Mukra\nZone:\nZuldazar\nKosten:\n350" }
