entries[174380] = { ["name"] = "Einigkeit des Gladiators", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\n+75 Ausdauer\nErhöht Eure PvP-Macht um + 96.\nAnlegen: Eure Fähigkeiten haben eine hohe Chance, 'Vorherrschaft des Gladiators' auszulösen, was Eure Hauptwert 15 Sek. lang um einen Wert entsprechend Eurer PvP-Macht erhöht.\nVerkaufspreis:" }
entries[174382] = { ["name"] = "Todeslotuspulver", ["text"] = "Questgegenstand\nBenutzen: Gewährt Schutz vor den Fallen im Spiegel der Gräfin.\n\"Ein unter anderem aus gemahlenem Todeslotus hergestelltes Pulver. Bekannt für seine Verwendung bei Venthyrzaubern.\"" }
