entries[174836] = { ["name"] = "Erweckter Gedankenbohrer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er mag jetzt ein wenig bedrohlich wirken, doch wenn er schläft, ist er richtig niedlich.\"\nErfolg:\nSchlüsselsteinmeister von Battle for Azeroth: Saison 4\nKategorie:\nDungeons" }
