entries[174840] = { ["name"] = "Xinlao", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur eines ist einem Qilen wichtiger als seine Treue: seinen Besitzer mit Küsschen zu bedecken.\"\nBeute von:\nAnh-De der Loyale\nZone:\nTal der Ewigen Blüten" }
entries[174841] = { ["name"] = "Rens tapferer Jagdhund", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Hundmeister Ren ließ sich von seinem stärksten Qilen durch Pandaria tragen, um das Tal im Namen des Mogureichs zu unterwerfen.\"\nBeute von:\nHundmeister Ren\nZone:\nTal der Ewigen Blüten" }
entries[174842] = { ["name"] = "Leicht klammer Pelzhaufen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dank ihres freundlichen Gemüts geben Alpakas die perfekten Begleiter für unerschrockene Abenteurer ab.\"\nBeute von:\nDünenschlinger Kraulok\nZone:\nVol'dun" }
