entries[174859] = { ["name"] = "Zügel des Frühlingsfellalpakas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dank ihres freundlichen Gemüts geben Alpakas die perfekten Begleiter für unerschrockene Abenteurer ab.\"\nQuest:\nWir alpaken's dann mal\nZone:\nUldum" }
