entries[174861] = { ["name"] = "Zuckender Parasit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er ist ständig in Bewegung! Das wirkt chaotisch und beunruhigend auf den Beobachter.\"\nErfolg:\nRuhm des Schlachtzüglers von Ny'alotha\nKategorie:\nDungeons & Schlachtzüge" }
entries[174862] = { ["name"] = "Unverderbte Leerenschwinge", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Brut von Vexiona wurde von Furorion geläutert und entstammt einem Drachenschwarm mit einer zerrütteten Vergangenheit und einer ungewissen Zukunft.\"\nQuest:\nVerlorener Schwarm" }
entries[174863] = { ["name"] = "Brut von Vexiona", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Stammt aus dem Gelege des gefallenen Drachen und wurde tief in N'Zoths Innerem gefunden.\"" }
entries[174864] = { ["name"] = "Jagdhorn des Dromanen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lasst das Dromanenhorn ertönen, um die Wilde Jagd zum Winterschlafbecken zu rufen. (4 Sek. Abklingzeit)\n\"Ein uraltes hölzernes Horn.\"" }
entries[174865] = { ["name"] = "Ein winziger Winterhut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wenn Pepe beschworen wird, ist er manchmal gekleidet wie Altvater Winter." }
entries[174867] = { ["name"] = "Splitter der Verderbnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 1 tag (Realzeit)\nDieser Gegenstand startet eine Quest.\n\"Ein dichtes Miasma der Verderbnis geht von dem Splitter aus. Er fühlt sich enorm schwer an, und wer ihn trägt, wird von Gefühlen der Unterdrückung und Boshaftigkeit überwältigt.\"" }
entries[174871] = { ["name"] = "Verwirrender Verstandverschmelzer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ihr erhaltet 30 Sek. lang die Kontrolle über Euer Haustier. (2 Min Abklingzeit)" }
entries[174872] = { ["name"] = "Allseher von Ny'alotha", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Um ihn zu finden, müsst Ihr Euch im Kreis der Sterne ertränken.\"\nBeute:\nN'Zoth der Verderber\nZone:\nNy'alotha, die Erwachte Stadt\nSchwierigkeitsgrad:\nMythisch" }
entries[174873] = { ["name"] = "Trans-mogu-fizierer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Verwandelt Euch in ein Mitglied eines der vier streitenden Moguklans. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[174874] = { ["name"] = "Einfache K'thirverkleidung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ruft einen Freund aus den Tiefen, der dann auf Eurem Kopf ruht. (1 Stunde Abklingzeit)\n\"Eine Verkleidung, die nur bei den nachlässigsten K'thir funktioniert.\"\nVerkaufspreis:" }
entries[174875] = { ["name"] = "Obelisk der Sonne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt einen Obelisken auf, der den Zorn der Sonne auf Eure Gegner niedergehen lässt und dabei Feuerschaden verursacht.\n\nKann nur in Uldum, im Tal der Ewigen Blüten, in Kul Tiras, Zandalar und Nazjatar genutzt werden. Hält 30 Sek. lang an. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[174876] = { ["name"] = "Ausgestochenes Auge von N'Zoth", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verzerrt latente Verderbnis zu einem Sockel für ein Ausrüstungsteil, das noch nicht über einen Sockel verfügt.\nErfordert den Erfolg \"Wir haben die Technologie\"." }
