entries[174920] = { ["name"] = "Haubenlockes Glattrasurset", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert Haubenlockes Glattrasurset auf dem Boden, sodass Ihr und andere es begutachten könnt. ACHTUNG: Rasurset steht möglicherweise unter finsteren Einflüssen. Zufriedenheit nicht garantiert! (1 Stunde Abklingzeit)" }
entries[174921] = { ["name"] = "Leerenberührter Schädel", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Werft den Schädel zu einem verbündeten Ziel, um das Spiel zu beginnen. Wenn er seine Leerenenergie abgibt, dürft Ihr ihn nicht in Händen halten, sonst habt Ihr verloren. (30 Min Abklingzeit)" }
entries[174922] = { ["name"] = "Leerenberührter Schädel", ["text"] = "Wird beim Aufheben gebunden\nDauer: 5 min (Realzeit)\nBenutzen: Werft den Schädel zu einem verbündeten Ziel, um das Spiel zu beginnen. Wenn er seine Leerenenergie abgibt, dürft Ihr ihn nicht in Händen halten, sonst habt Ihr verloren." }
entries[174923] = { ["name"] = "Dämmermoorelixier", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Nach dem Verzehr zwingt Eure Stimme andere, die Wahrheit zu sagen. (5 Sek. Abklingzeit)" }
entries[174924] = { ["name"] = "Leerenberührtes Souvenirtotem", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert das Totem zu Euren Füßen. ACHTUNG: Von Kleintieren fernhalten, es sei denn, Ihr mögt sie lieber, wenn sie groß und wütend sind. (30 Min Abklingzeit)\n\"Nicht für kleine Tiere geeignet.\"" }
entries[174925] = { ["name"] = "Leerententakelhaustierleine", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Eine passendere Leine für Eure leerenberührten Haustiere... oder auch für alle anderen, die Manieren lernen sollen.\n80 ( 80)\nBenötigt einen freundlichen Ruf beim Abkommen von Uldum.\nVerkaufspreis:" }
entries[174926] = { ["name"] = "Überempfindliche Leerenbrille", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Gestattet es Euch, Leerenbedrohungen zu sehen, wo auch immer sie herumkriechen mögen. (30 Min Abklingzeit)" }
