entries[175246] = { ["name"] = "N'lyeth, Splitter von N'Zoth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Opfert einen Teil Eurer sterblichen Essenz und fügt Euch selbst Schattenschaden in Höhe von 60% Eurer maximalen Gesundheit zu.\n\nIm Gegenzug werdet Ihr zu einem Shath'Yar, verliert Eure normale Fraktionstreue und dient nur noch N'Zoth.\n\nN'lyeth kann nur im Freien in Kul Tiras und Zandalar sowie in Visionen von N'Zoth verwendet werden, während Ihr Euch im Kriegsmodus befindet. (1 Stunde Abklingzeit)" }
entries[175247] = { ["name"] = "Ungewöhnlich großer Pilz", ["text"] = "Einzigartig\nDauer: 20 min (Realzeit)\n\"Dieser schnell vergammelnde Pilz benötigt zum Überleben lehmige Erde.\"" }
entries[175248] = { ["name"] = "Klinge des selbstlosen Bringers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nSchließt Kapitel 9 Eurer Paktkampagne ab\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[175249] = { ["name"] = "Wurfspeer des selbstlosen Sammlers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n1 - 3 Schaden Geschwindigkeit 3.60\n(0.6 Schaden pro Sekunde)\nHaltbarkeit 35 / 35\nSchließt Kapitel 9 Eurer Paktkampagne ab\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[175251] = { ["name"] = "Gegabelte Klinge der Seelenstärke", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n15 - 26 Schaden Geschwindigkeit 1.80\n(11.4 Schaden pro Sekunde)\n+10 Beweglichkeit\n+15 Ausdauer\nErhöht Eure kritische Trefferwertung um + 13.\nErhöht Eure Meisterschaftswertung um + 7.\nHaltbarkeit 80 / 80\nVerkaufspreis:" }
